"""Generate a self-contained static project page; publication copies site/ into GitHub Pages docs/."""
from pathlib import Path
import json,shutil,html
from PIL import Image
R=Path(__file__).resolve().parents[1];S=R/'site';A=S/'assets';A.mkdir(parents=True,exist_ok=True);C=json.loads((R/'config.json').read_text());credits={x['id']:x for x in json.loads((R/'data/photo-credits.json').read_text())};esc=lambda v:html.escape(str(v),quote=True)
for name in ['seeing-the-hudson.png','seeing-the-hudson-preview.png','05-thomas-hagos.png','pair-01.png','pair-02.png','pair-03.png']:shutil.copy2(R/'outputs'/name,A/name)
for p in C['pairs']:
 for side in ['nj','ny']:
  k=p[side]['photo'];shutil.copy2(R/'data/raw/photos'/(k+'.jpg'),A/(k+'.jpg'))
for src,name in [(R/'data/processed/viewpoints.csv','viewpoints.csv'),(R/'data/photo-credits.json','photo-credits.json'),(R/'README.md','methods.md')]:shutil.copy2(src,A/name)
sections=[]
for p in C['pairs']:
 cards=[]
 for side in ['nj','ny']:
  s=p[side];r=credits[s['photo']];cards.append(f'''<figure class="photo"><img loading="lazy" src="assets/{r['id']}.jpg" alt="{esc(r['title'].removeprefix('File:') if hasattr(str,'removeprefix') else r['title'])}"><figcaption><span class="eyebrow">{side.upper()} / {esc(s['short'])}</span><h3>{esc(s['view'])}</h3><p>{esc(s['observation'])}</p><small>Photograph: <a href="{esc(r['page_url'])}">{esc(r['creator'])}</a> · {esc(r['capture_date'][:10])} · <a href="{esc(r['license_url'])}">{esc(r['license'])}</a>. Resized/cropped detail; original linked above.</small><p class="site"><a href="{esc(s['source'])}">Official park information ↗</a></p></figcaption></figure>''')
 sections.append(f'''<section id="pair-{p['id']}"><div class="section-heading"><span class="index" style="color:{p['color']}">{p['id']}</span><div><span class="eyebrow">{esc(p['region'])}</span><h2>{esc(p['title'])}</h2></div></div><p class="section-intro">{esc(p['story'])}</p><div class="photo-grid">{''.join(cards)}</div><details><summary>Locate these two places</summary><a href="assets/pair-{p['id']}.png"><img class="pair-sheet" loading="lazy" src="assets/pair-{p['id']}.png" alt="North-up georeferenced aerial map and photographs of the {esc(p['title'])} site pairing"></a><p class="note">The dashed line pairs sites; it is not a verified sightline. USGS orthoimagery mosaic; exact local capture dates unresolved. Coordinates are approximate; Fort Lee uses the park entrance anchor.</p></details></section>''')
h='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Two shores. One river. Different views. A mapped photographic essay on six public places along the New York–New Jersey Hudson waterfront, by Thomas Hagos."><meta property="og:title" content="Seeing the Hudson — Thomas Hagos"><meta property="og:description" content="Two shores. One river. Different views."><meta property="og:image" content="https://flex-commits.github.io/30-days-mapping/seeing-the-hudson/assets/seeing-the-hudson-preview.png"><title>Seeing the Hudson — Thomas Hagos</title><style>
:root{color-scheme:dark;--bg:#101e2b;--fg:#f2eee2;--muted:#a8b7c2;--gold:#edb969;--line:#405562}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--fg);font:17px/1.65 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1160px;margin:auto;padding:44px 36px}a{color:var(--gold);text-underline-offset:4px}a:hover{color:var(--fg)}.top{display:flex;justify-content:space-between;gap:20px;font-size:12px;border-top:1px solid var(--gold);padding-top:18px}.eyebrow{font-size:11px;letter-spacing:.11em;color:var(--gold);font-weight:650;text-transform:uppercase}h1{font-size:clamp(48px,8vw,100px);line-height:1.02;letter-spacing:-.055em;margin:48px 0 20px;max-width:900px}h2{font-size:clamp(27px,4vw,43px);line-height:1.1;letter-spacing:-.03em;margin:8px 0}h3{font-size:20px;line-height:1.3;margin:12px 0}.subtitle{font-size:clamp(21px,3vw,31px);color:var(--muted);margin:0 0 24px}.intro{max-width:700px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:30px 0}.actions a{display:inline-block;border:1px solid var(--line);border-radius:2px;padding:10px 16px;text-decoration:none;font-size:13px}.actions a.primary{background:var(--gold);color:var(--bg);border-color:var(--gold);font-weight:650}.toc{display:flex;flex-wrap:wrap;gap:22px;font-size:13px;border-top:1px solid var(--line);padding-top:22px;margin-top:34px}img{max-width:100%;height:auto;display:block}.poster{margin:35px 0 0;background:#152633;padding:18px}.poster img{max-height:980px;width:auto;margin:auto}.poster figcaption{font-size:12px;color:var(--muted);max-width:800px;margin:18px auto 0}.note,small{color:var(--muted);font-size:12px;line-height:1.7}section{padding-top:65px;margin-top:35px;border-top:1px solid var(--line);scroll-margin-top:20px}.section-heading{display:flex;gap:20px;align-items:baseline}.index{font-size:45px;line-height:1;font-weight:700}.section-intro{max-width:700px;color:var(--muted)}.photo-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:30px 0}.photo{margin:0}.photo img{width:100%;height:280px;object-fit:cover;background:#172c39}.photo figcaption{padding:20px 0}.photo p{font-size:14px}.site a{font-size:12px}details{border:1px solid var(--line);padding:16px 20px}summary{cursor:pointer;font-size:14px;color:var(--gold)}.pair-sheet{max-width:650px;margin:20px auto}.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:35px}.method-grid p{font-size:14px;color:var(--muted)}footer{border-top:1px solid var(--line);margin-top:65px;padding:25px 0 10px;font-size:12px;color:var(--muted)}:focus-visible{outline:2px solid var(--gold);outline-offset:4px}@media(max-width:700px){main{padding:25px 20px}.top{display:block}.top span{display:block;margin-top:7px}h1{margin-top:35px}.photo-grid,.method-grid{grid-template-columns:1fr}.photo img{height:auto}.poster{padding:5px}.index{font-size:32px}.section-heading{gap:14px}section{padding-top:35px}.toc{gap:15px}footer{margin-top:40px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body><main><header><div class="top"><a href="../">THOMAS HAGOS / 30-DAY MAP CHALLENGE</a><span>2026 · DAY 05 · SENSES: SIGHT</span></div><h1>Seeing<br>the Hudson.</h1><p class="subtitle">Two shores. One river. Different views.</p><p class="intro">New York and New Jersey share a river. What you see depends on where you stand—and when you look.</p><p class="intro">I paired six public places along the Lower Hudson with dated photographs and aerial maps. A skyline, a sunset, a bridge: familiar things, framed differently from the two shores.</p><div class="actions"><a class="primary" href="assets/seeing-the-hudson.png">Download the full map</a><a href="https://github.com/Flex-commits/30-days-mapping/tree/main/day05-seeing-hudson">Code & sources</a><a href="#reading">How to read it</a></div><nav aria-label="Site pairings" class="toc"><a href="#pair-01">01 / Skyline to skyline</a><a href="#pair-02">02 / A skyline. A sunset.</a><a href="#pair-03">03 / One bridge. Two frames.</a></nav></header><figure class="poster"><a href="assets/seeing-the-hudson.png"><img src="assets/seeing-the-hudson-preview.png" alt="Seeing the Hudson: an aerial map of six New York and New Jersey public sites with three pairs of credited historical waterfront photographs."></a><figcaption>Click to open the full-resolution map. Dashed connections are editorial pairings, not verified sightlines. The three numbered map frames are enlarged in the paired-site sheets below.</figcaption></figure>__SECTIONS__<section id="reading"><span class="eyebrow">Sources & method</span><h2>A visual essay,<br>not a visibility model.</h2><div class="method-grid"><div><h3>What the map shows</h3><p>Six approximate public-site anchors, three editorial connections, and real aerial geography. Geographic frames are north-up in NAD83 / UTM zone 18N (EPSG:26918); scale bars use miles. Five anchors use photographer-supplied coordinates; Fort Lee uses the park operator’s entrance GPS, not the camera position.</p><p>No line certifies that a person at one point can see its paired point. This is not a comprehensive access inventory, viewshed analysis or current-condition survey.</p></div><div><h3>What the dates mean</h3><p>The USDA/USGS cached orthoimagery service reports continental-U.S. NAIP sources from 2017–2021; exact local pixel dates are not exposed. A June 2024 service refresh is not an image acquisition date. It is aerial photography, not satellite imagery. Original coverage gaps and date differences remain limitations. The maps are darkened for labels; near-black source pixels display transparently over navy.</p><p>The photographs date from 2008–2022. Different seasons, weather, times and fields of view mean these are not controlled comparisons. The five 4.0 photographs and one 3.0 photograph use CC BY-SA licenses, with creators, dates and linked source pages beside each image.</p></div></div><div class="actions"><a href="assets/viewpoints.csv">Viewpoint records CSV</a><a href="assets/photo-credits.json">Full photo credits</a><a href="https://github.com/Flex-commits/30-days-mapping/blob/main/day05-seeing-hudson/README.md">Complete methods</a></div></section><footer>Map and text: Thomas Hagos. Photographs by Dtabb73, Kidfly182, Famartin, G. Scott Segler, Jllm06 and Jmccabe371, via Wikimedia Commons (CC BY-SA 4.0; Jmccabe371 source CC BY-SA 3.0, as linked above). Composition: <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Poster, sheets and cards use resized/cropped photographic details; originals are linked. Aerial imagery: USDA / USGS / The National Map. DejaVu Sans. No agency endorsement implied.<br><br>#30DayMapChallenge · #teamMUSA · <a href="https://github.com/Flex-commits/30-days-mapping">Repository</a></footer></main></body></html>'''.replace('__SECTIONS__',''.join(sections))
(S/'index.html').write_text(h);print(S/'index.html')
